const files = {
  "src/modules/signing/types.ts": "export interface CertificateData {\n  privateKeyPem: string;\n  certificatePem: string;\n  subject?: string;\n  issuer?: string;\n  serialNumber?: string;\n  validFrom?: Date;\n  validTo?: Date;\n}\n\nexport interface SignXmlOptions {\n  /** Id del nodo ds:Signature (por defecto \"SignatureSP\") */\n  signatureId?: string;\n  /** Algoritmo de firma RSA: 'sha1' (estándar tradicional SUNAT UBL 2.1) o 'sha256' */\n  algorithm?: 'sha1' | 'sha256';\n}\n\nexport interface SignatureResult {\n  /** XML firmado con el elemento ds:Signature insertado dentro de ext:ExtensionContent */\n  signedXml: string;\n  /** Hash del comprobante (DigestValue en Base64). Obligatorio para QR y PDF */\n  hashCpe: string;\n  /** Valor de la firma criptográfica (SignatureValue en Base64) */\n  signatureValue: string;\n  /** Algoritmo utilizado */\n  algorithm: string;\n}\n\nexport interface VerifySignatureResult {\n  isValid: boolean;\n  error?: string;\n}\n",
  "src/modules/signing/certificate.service.ts": "import forge from 'node-forge';\nimport type { CertificateData } from './types.js';\n\n/**\n * Carga un certificado digital desde un archivo PKCS#12 (.pfx / .p12) y su contraseña.\n * Extrae la clave privada RSA en formato PEM y el certificado X.509.\n */\nexport function loadCertificateFromPfx(pfxBuffer: Buffer | Uint8Array, password = ''): CertificateData {\n  try {\n    const binaryStr = Buffer.from(pfxBuffer).toString('binary');\n    const p12Asn1 = forge.asn1.fromDer(binaryStr);\n    const p12 = forge.pkcs12.pkcs12FromAsn1(p12Asn1, password);\n\n    let keyPem = '';\n    let certPem = '';\n    let certObj: forge.pki.Certificate | null = null;\n\n    for (const safeContent of p12.safeContents) {\n      for (const safeBag of safeContent.safeBags) {\n        if (safeBag.key) {\n          keyPem = forge.pki.privateKeyToPem(safeBag.key);\n        }\n        if (safeBag.cert) {\n          certPem = forge.pki.certificateToPem(safeBag.cert);\n          certObj = safeBag.cert;\n        }\n      }\n    }\n\n    if (!keyPem) {\n      throw new Error('No se encontró la clave privada RSA en el archivo PFX proporcionado.');\n    }\n    if (!certPem) {\n      throw new Error('No se encontró el certificado X.509 en el archivo PFX proporcionado.');\n    }\n\n    const subjectAttrs = certObj?.subject?.attributes?.map((a: any) => `${a.shortName || a.name}=${a.value}`).join(', ');\n    const issuerAttrs = certObj?.issuer?.attributes?.map((a: any) => `${a.shortName || a.name}=${a.value}`).join(', ');\n\n    return {\n      privateKeyPem: keyPem,\n      certificatePem: certPem,\n      subject: subjectAttrs,\n      issuer: issuerAttrs,\n      serialNumber: certObj?.serialNumber,\n      validFrom: certObj?.validity?.notBefore,\n      validTo: certObj?.validity?.notAfter,\n    };\n  } catch (err: any) {\n    if (err.message && err.message.includes('No se encontró')) {\n      throw err;\n    }\n    throw new Error(`Error al procesar el archivo PFX/P12: Contraseña incorrecta o formato inválido (${err.message})`);\n  }\n}\n\n/**\n * Carga directamente un par de clave privada y certificado ya convertidos a PEM.\n */\nexport function loadCertificateFromPem(privateKeyPem: string, certificatePem: string): CertificateData {\n  if (!privateKeyPem.includes('PRIVATE KEY')) {\n    throw new Error('La clave privada no contiene el encabezado PEM válido (PRIVATE KEY).');\n  }\n  if (!certificatePem.includes('CERTIFICATE')) {\n    throw new Error('El certificado no contiene el encabezado PEM válido (CERTIFICATE).');\n  }\n\n  let certObj: forge.pki.Certificate | null = null;\n  try {\n    certObj = forge.pki.certificateFromPem(certificatePem);\n  } catch {\n    // Si no se puede parsear metadatos opcionales, igual dejamos pasar los PEM\n  }\n\n  const subjectAttrs = certObj?.subject?.attributes?.map((a: any) => `${a.shortName || a.name}=${a.value}`).join(', ');\n  const issuerAttrs = certObj?.issuer?.attributes?.map((a: any) => `${a.shortName || a.name}=${a.value}`).join(', ');\n\n  return {\n    privateKeyPem,\n    certificatePem,\n    subject: subjectAttrs,\n    issuer: issuerAttrs,\n    serialNumber: certObj?.serialNumber,\n    validFrom: certObj?.validity?.notBefore,\n    validTo: certObj?.validity?.notAfter,\n  };\n}\n\n/**\n * Genera un certificado autofirmado en memoria para pruebas de desarrollo sin depender de archivos externos.\n */\nexport function generateSelfSignedCertificate(commonName = 'CERTIFICADO DE PRUEBA SUNAT', password = 'sunat'): {\n  pfxBuffer: Buffer;\n  password: string;\n  certData: CertificateData;\n} {\n  const keys = forge.pki.rsa.generateKeyPair(2048);\n  const cert = forge.pki.createCertificate();\n  cert.publicKey = keys.publicKey;\n  cert.serialNumber = '01' + Date.now();\n  cert.validity.notBefore = new Date();\n  cert.validity.notAfter = new Date();\n  cert.validity.notAfter.setFullYear(cert.validity.notBefore.getFullYear() + 1);\n\n  const attrs = [\n    { name: 'commonName', value: commonName },\n    { name: 'organizationName', value: 'EMPRESA DE PRUEBA SUNAT' },\n    { name: 'countryName', value: 'PE' },\n  ];\n  cert.setSubject(attrs);\n  cert.setIssuer(attrs);\n  cert.sign(keys.privateKey, forge.md.sha256.create());\n\n  const p12Asn1 = forge.pkcs12.toPkcs12Asn1(keys.privateKey, [cert], password, {\n    algorithm: '3des',\n  });\n  const p12Der = forge.asn1.toDer(p12Asn1).getBytes();\n  const pfxBuffer = Buffer.from(p12Der, 'binary');\n\n  const certData: CertificateData = {\n    privateKeyPem: forge.pki.privateKeyToPem(keys.privateKey),\n    certificatePem: forge.pki.certificateToPem(cert),\n    subject: `CN=${commonName}`,\n    validFrom: cert.validity.notBefore,\n    validTo: cert.validity.notAfter,\n  };\n\n  return {\n    pfxBuffer,\n    password,\n    certData,\n  };\n}\n",
  "src/modules/signing/xml-signer.ts": "import { SignedXml } from 'xml-crypto';\nimport { DOMParser } from '@xmldom/xmldom';\nimport type { CertificateData, SignXmlOptions, SignatureResult, VerifySignatureResult } from './types.js';\n\n/**\n * Firma un XML de comprobante electrónico (Factura, Boleta o Nota) según la especificación\n * oficial de SUNAT UBL 2.1 (Enveloped Signature, C14N, RSA-SHA1 o RSA-SHA256).\n *\n * Devuelve el XML firmado y el hash del CPE (DigestValue), esencial para el código QR y la representación impresa.\n */\nexport function signUblXml(\n  xml: string,\n  cert: CertificateData,\n  options: SignXmlOptions = {},\n): SignatureResult {\n  if (!xml || typeof xml !== 'string') {\n    throw new Error('El XML a firmar no puede estar vacío.');\n  }\n  if (!cert.privateKeyPem || !cert.certificatePem) {\n    throw new Error('Se requiere la clave privada y el certificado X.509 para firmar el documento.');\n  }\n\n  const signatureId = options.signatureId ?? 'SignatureSP';\n  const algorithm = options.algorithm ?? 'sha1';\n\n  const digestAlgorithm =\n    algorithm === 'sha256'\n      ? 'http://www.w3.org/2001/04/xmlenc#sha256'\n      : 'http://www.w3.org/2000/09/xmldsig#sha1';\n\n  const signatureAlgorithm =\n    algorithm === 'sha256'\n      ? 'http://www.w3.org/2001/04/xmldsig-more#rsa-sha256'\n      : 'http://www.w3.org/2000/09/xmldsig#rsa-sha1';\n\n  // Si el XML ya contenía un placeholder o firma anterior dentro de ExtensionContent, lo limpiamos\n  const normalizedXml = xml.replace(\n    /<(?:ext:)?ExtensionContent>[\\s\\S]*?<\\/(?:ext:)?ExtensionContent>/,\n    '<ext:ExtensionContent/>',\n  );\n\n  const sig = new SignedXml();\n  sig.addReference({\n    xpath: '/*',\n    transforms: ['http://www.w3.org/2000/09/xmldsig#enveloped-signature'],\n    digestAlgorithm,\n    isEmptyUri: true,\n  });\n\n  sig.canonicalizationAlgorithm = 'http://www.w3.org/TR/2001/REC-xml-c14n-20010315';\n  sig.signatureAlgorithm = signatureAlgorithm;\n  sig.privateKey = cert.privateKeyPem;\n  sig.publicCert = cert.certificatePem;\n\n  sig.computeSignature(normalizedXml, {\n    location: {\n      reference: '//*[local-name(.)=\"ExtensionContent\"]',\n      action: 'append',\n    },\n    attrs: {\n      Id: signatureId,\n    },\n  });\n\n  const signedXml = sig.getSignedXml();\n\n  // Extraer DigestValue (Hash del CPE)\n  const digestMatch = signedXml.match(/<(?:\\w+:)?DigestValue>([^<]+)<\\/(?:\\w+:)?DigestValue>/);\n  if (!digestMatch) {\n    throw new Error('No se pudo extraer el DigestValue (Hash del comprobante) tras la firma.');\n  }\n  const hashCpe = digestMatch[1].trim();\n\n  // Extraer SignatureValue\n  const sigMatch = signedXml.match(/<(?:\\w+:)?SignatureValue>([^<]+)<\\/(?:\\w+:)?SignatureValue>/);\n  const signatureValue = sigMatch ? sigMatch[1].replace(/\\s+/g, '') : '';\n\n  return {\n    signedXml,\n    hashCpe,\n    signatureValue,\n    algorithm: `rsa-${algorithm}`,\n  };\n}\n\n/**\n * Extrae el Hash oficial del comprobante (DigestValue) desde un XML ya firmado.\n */\nexport function extractHashCpe(signedXml: string): string {\n  const match = signedXml.match(/<(?:\\w+:)?DigestValue>([^<]+)<\\/(?:\\w+:)?DigestValue>/);\n  if (!match) {\n    throw new Error('No se encontró el elemento DigestValue en el XML firmado.');\n  }\n  return match[1].trim();\n}\n\n/**\n * Valida la integridad criptográfica de un XML firmado.\n * Si no se proporciona un certificado explícito, intenta usar el certificado incrustado en el XML.\n */\nexport function verifySignedXml(signedXml: string, customCertPem?: string): VerifySignatureResult {\n  try {\n    const doc = new DOMParser().parseFromString(signedXml, 'text/xml');\n    const signatureNodes = doc.getElementsByTagNameNS('http://www.w3.org/2000/09/xmldsig#', 'Signature');\n    if (!signatureNodes.length) {\n      return { isValid: false, error: 'No se encontró el elemento Signature en el documento XML.' };\n    }\n    const signatureNode = signatureNodes[0];\n\n    let certPem = customCertPem;\n    if (!certPem) {\n      const certNodes = doc.getElementsByTagNameNS('http://www.w3.org/2000/09/xmldsig#', 'X509Certificate');\n      if (!certNodes.length || !certNodes[0].textContent) {\n        return { isValid: false, error: 'No se encontró el certificado X.509 en la firma.' };\n      }\n      certPem = `-----BEGIN CERTIFICATE-----\\n${certNodes[0].textContent.trim()}\\n-----END CERTIFICATE-----`;\n    }\n\n    const verifier = new SignedXml();\n    verifier.publicCert = certPem;\n    verifier.loadSignature(signatureNode);\n    const isValid = verifier.checkSignature(signedXml);\n\n    return {\n      isValid,\n      error: isValid ? undefined : (verifier as any).validationErrors?.join(', ') || 'La firma criptográfica no es válida.',\n    };\n  } catch (err: any) {\n    return {\n      isValid: false,\n      error: err.message ?? 'Error desconocido durante la verificación de la firma.',\n    };\n  }\n}\n",
  "src/modules/signing/index.ts": "export * from './types.js';\nexport * from './certificate.service.js';\nexport * from './xml-signer.js';\n",
  "src/modules/packaging/types.ts": "export interface CpePackageInfo {\n  /** RUC del emisor (11 dígitos) */\n  ruc: string;\n  /** Código de tipo de comprobante SUNAT: '01' (Factura), '03' (Boleta), '07' (NC) */\n  cpeType: string;\n  /** Serie del comprobante (4 caracteres, ej. F001, B001, FC01) */\n  series: string;\n  /** Número correlativo (número entero o cadena, se rellena a 8 dígitos) */\n  correlative: number | string;\n}\n\nexport interface ZipPackageResult {\n  /** Nombre base oficial del comprobante: {RUC}-{TIPO}-{SERIE}-{NUMERO} */\n  baseName: string;\n  /** Nombre del archivo XML dentro del ZIP */\n  xmlFileName: string;\n  /** Nombre oficial del archivo ZIP */\n  zipFileName: string;\n  /** Buffer binario del archivo ZIP comprimido */\n  zipBuffer: Buffer;\n  /** Archivo ZIP codificado en Base64 para envío SOAP (sendBill) */\n  zipBase64: string;\n  /** Tamaño del archivo ZIP en bytes */\n  fileSize: number;\n}\n\nexport interface UnzippedCpeResult {\n  xmlFileName: string;\n  xmlContent: string;\n}\n",
  "src/modules/packaging/zip-packager.ts": "import JSZip from 'jszip';\nimport type { CpePackageInfo, UnzippedCpeResult, ZipPackageResult } from './types.js';\n\n/**\n * Valida y formatea el nombre base oficial exigido por SUNAT:\n * {RUC}-{TIPO_CPE}-{SERIE}-{CORRELATIVO}\n * Ejemplo: 20600000001-01-F001-00000001\n */\nexport function formatCpeFileName(info: CpePackageInfo): string {\n  const ruc = String(info.ruc || '').trim();\n  if (!/^\\d{11}$/.test(ruc)) {\n    throw new Error(`RUC inválido para nomenclatura SUNAT: \"${ruc}\". Debe tener 11 dígitos numéricos.`);\n  }\n\n  const cpeType = String(info.cpeType || '').trim().padStart(2, '0');\n  if (!/^\\d{2}$/.test(cpeType)) {\n    throw new Error(`Tipo de comprobante inválido: \"${info.cpeType}\". Debe tener 2 dígitos (ej. 01, 03, 07).`);\n  }\n\n  const series = String(info.series || '').trim().toUpperCase();\n  if (!/^[A-Z0-9]{4}$/.test(series)) {\n    throw new Error(`Serie inválida: \"${info.series}\". Debe tener exactamente 4 caracteres alfanuméricos (ej. F001, B001).`);\n  }\n\n  const correlativeNum = parseInt(String(info.correlative), 10);\n  if (isNaN(correlativeNum) || correlativeNum <= 0 || correlativeNum > 99999999) {\n    throw new Error(`Correlativo inválido: \"${info.correlative}\". Debe ser un número entre 1 y 99999999.`);\n  }\n  const correlative = String(correlativeNum).padStart(8, '0');\n\n  return `${ruc}-${cpeType}-${series}-${correlative}`;\n}\n\n/**\n * Empaqueta un XML firmado en un archivo ZIP con la nomenclatura y estructura requerida por SUNAT:\n * Archivo: {RUC}-{TIPO}-{SERIE}-{CORRELATIVO}.zip\n * Contenido interno: {RUC}-{TIPO}-{SERIE}-{CORRELATIVO}.xml (directamente en la raíz del ZIP, sin subcarpetas).\n */\nexport async function createCpeZip(info: CpePackageInfo, signedXml: string): Promise<ZipPackageResult> {\n  if (!signedXml || typeof signedXml !== 'string') {\n    throw new Error('El XML a empaquetar no puede estar vacío.');\n  }\n\n  const baseName = formatCpeFileName(info);\n  const xmlFileName = `${baseName}.xml`;\n  const zipFileName = `${baseName}.zip`;\n\n  const zip = new JSZip();\n  // Regla estricta SUNAT: exactamente 1 archivo en la raíz del ZIP\n  zip.file(xmlFileName, signedXml);\n\n  const zipBuffer = await zip.generateAsync({\n    type: 'nodebuffer',\n    compression: 'DEFLATE',\n    compressionOptions: {\n      level: 6,\n    },\n  });\n\n  return {\n    baseName,\n    xmlFileName,\n    zipFileName,\n    zipBuffer,\n    zipBase64: zipBuffer.toString('base64'),\n    fileSize: zipBuffer.length,\n  };\n}\n\n/**\n * Descomprime y extrae el XML de un paquete CPE o de una Constancia de Recepción (CDR) de SUNAT.\n */\nexport async function extractCpeZip(zipInput: Buffer | Uint8Array | string): Promise<UnzippedCpeResult> {\n  const zipBuffer = typeof zipInput === 'string' ? Buffer.from(zipInput, 'base64') : Buffer.from(zipInput);\n  const zip = await JSZip.loadAsync(zipBuffer);\n\n  const fileNames = Object.keys(zip.files).filter((name) => !zip.files[name].dir);\n  if (!fileNames.length) {\n    throw new Error('El archivo ZIP no contiene ningún archivo.');\n  }\n\n  // Buscar el archivo XML\n  const xmlName = fileNames.find((name) => name.toLowerCase().endsWith('.xml')) || fileNames[0];\n  const xmlFile = zip.file(xmlName);\n  if (!xmlFile) {\n    throw new Error(`No se pudo leer el archivo ${xmlName} dentro del ZIP.`);\n  }\n\n  const xmlContent = await xmlFile.async('text');\n  return {\n    xmlFileName: xmlName,\n    xmlContent,\n  };\n}\n",
  "src/modules/packaging/index.ts": "export * from './types.js';\nexport * from './zip-packager.js';\n",
  "src/modules/sunat-soap/types.ts": "export type SunatEnvironment = 'beta' | 'production' | 'custom';\n\nexport interface SunatCredentials {\n  /** RUC del emisor (11 dígitos) */\n  ruc: string;\n  /** Usuario secundario SOL (ej. MODDATOS) */\n  username: string;\n  /** Clave SOL del usuario secundario */\n  password: string;\n}\n\nexport interface SunatClientConfig {\n  credentials: SunatCredentials;\n  /** 'beta' (homologación/pruebas) o 'production'. Por defecto 'beta' */\n  environment?: SunatEnvironment;\n  /** URL personalizada para pruebas de integración o mocks locales */\n  customUrl?: string;\n  /** Tiempo de espera máximo en milisegundos (por defecto 30000 ms = 30s) */\n  timeoutMs?: number;\n  /** Función fetch inyectable (útil para pruebas unitarias sin llamadas a red) */\n  fetchFn?: typeof fetch;\n}\n\nexport interface SoapFaultDetail {\n  faultCode: string;\n  faultString: string;\n  detail?: string;\n  sunatErrorCode?: string;\n}\n\nexport interface SunatCdrObservation {\n  code: string;\n  message: string;\n}\n\nexport interface SunatCdr {\n  /** Identificador de la CDR (ej. R-20600000001-01-F001-00000001) */\n  id: string;\n  /** Serie y correlativo del comprobante referenciado (ej. F001-00000001) */\n  referenceId: string;\n  /** Tipo de comprobante (ej. '01', '03', '07') */\n  documentTypeCode: string;\n  /** Código numérico de respuesta SUNAT: '0' (Aceptado), '0100'-'3999' (Rechazo), '4000'+ (Observación) */\n  responseCode: string;\n  /** Descripción textual devuelta por SUNAT */\n  description: string;\n  /** Indica si SUNAT aceptó formalmente el comprobante (responseCode === '0') */\n  isAccepted: boolean;\n  /** Indica si el comprobante fue aceptado pero cuenta con observaciones técnicas */\n  hasObservations: boolean;\n  /** Observaciones y advertencias devueltas por SUNAT */\n  observations: SunatCdrObservation[];\n  /** Notas textuales devueltas en cbc:Note */\n  notes: string[];\n  /** Fecha de emisión de la CDR por SUNAT (YYYY-MM-DD) */\n  issueDate: string;\n  /** Hora de emisión de la CDR (HH:mm:ss) */\n  issueTime: string;\n  /** Fecha y hora de recepción si están presentes */\n  responseDate?: string;\n  responseTime?: string;\n  /** RUC de SUNAT (habitualmente 20131312955) */\n  senderRuc?: string;\n  /** RUC del contribuyente receptor de la CDR */\n  receiverRuc?: string;\n  /** Hash criptográfico del CDR firmado por SUNAT (DigestValue) */\n  cdrHash?: string;\n  /** Firma de SUNAT (SignatureValue) */\n  signatureValue?: string;\n  /** Contenido XML íntegro de la CDR */\n  xmlContent: string;\n  /** Archivo ZIP original en Base64 devuelto por SUNAT (para almacenar en BD) */\n  zipBase64?: string;\n}\n\nexport type SendBillStatus =\n  | 'ACCEPTED'\n  | 'ACCEPTED_WITH_OBSERVATIONS'\n  | 'REJECTED'\n  | 'SOAP_FAULT'\n  | 'NETWORK_ERROR';\n\nexport interface SendBillResult {\n  /** Estado consolidado de la operación */\n  status: SendBillStatus;\n  /** Resumen del resultado */\n  message: string;\n  /** Código de estado HTTP retornado */\n  httpStatusCode: number;\n  /** Información parseada de la Constancia de Recepción (si SUNAT devolvió CDR) */\n  cdr?: SunatCdr;\n  /** Detalle del fallo si ocurrió un SOAP Fault */\n  fault?: SoapFaultDetail;\n  /** XML SOAP crudo devuelto por el servidor */\n  rawSoapResponse?: string;\n}\n",
  "src/modules/sunat-soap/soap-envelope.ts": "import type { SoapFaultDetail, SunatCredentials } from './types.js';\n\nexport const SUNAT_ENDPOINTS = {\n  beta: 'https://e-beta.sunat.gob.pe/ol-ti-itcpfegem-beta/billService',\n  production: 'https://e-facturacion.sunat.gob.pe/ol-ti-itcpfegem/billService',\n} as const;\n\n/**\n * Escapa caracteres especiales XML para valores de texto.\n */\nfunction escapeXml(value: string): string {\n  return value\n    .replace(/&/g, '&amp;')\n    .replace(/</g, '&lt;')\n    .replace(/>/g, '&gt;')\n    .replace(/\"/g, '&quot;')\n    .replace(/'/g, '&apos;');\n}\n\n/**\n * Construye el sobre SOAP 1.1 con WS-Security UsernameToken para la operación sendBill de SUNAT.\n */\nexport function buildSendBillEnvelope(\n  credentials: SunatCredentials,\n  fileName: string,\n  contentFileBase64: string,\n): string {\n  const username = `${credentials.ruc.trim()}${credentials.username.trim()}`;\n  const password = credentials.password;\n  const cleanFileName = fileName.trim();\n  const cleanContent = contentFileBase64.replace(/\\s+/g, '');\n\n  return `<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<soapenv:Envelope xmlns:soapenv=\"http://schemas.xmlsoap.org/soap/envelope/\"\n                  xmlns:ser=\"http://service.sunat.gob.pe\"\n                  xmlns:wsse=\"http://docs.oasis-open.org/wss/2004/01/oasis-200401-wss-wssecurity-secext-1.0.xsd\">\n  <soapenv:Header>\n    <wsse:Security>\n      <wsse:UsernameToken>\n        <wsse:Username>${escapeXml(username)}</wsse:Username>\n        <wsse:Password Type=\"http://docs.oasis-open.org/wss/2004/01/oasis-200401-wss-username-token-profile-1.0#PasswordText\">${escapeXml(password)}</wsse:Password>\n      </wsse:UsernameToken>\n    </wsse:Security>\n  </soapenv:Header>\n  <soapenv:Body>\n    <ser:sendBill>\n      <fileName>${escapeXml(cleanFileName)}</fileName>\n      <contentFile>${cleanContent}</contentFile>\n    </ser:sendBill>\n  </soapenv:Body>\n</soapenv:Envelope>`.trim();\n}\n\n/**\n * Extrae la respuesta applicationResponse (ZIP de la CDR en Base64) del sobre SOAP devuelto por SUNAT.\n */\nexport function extractApplicationResponse(soapXml: string): string | null {\n  if (!soapXml) return null;\n  const match = soapXml.match(/<(?:[a-zA-Z0-9_-]+:)?applicationResponse>([\\s\\S]*?)<\\/(?:[a-zA-Z0-9_-]+:)?applicationResponse>/);\n  if (!match) return null;\n  return match[1].replace(/\\s+/g, '');\n}\n\n/**\n * Detecta y parsea un SOAP Fault en la respuesta XML devuelta por SUNAT.\n */\nexport function parseSoapFault(soapXml: string): SoapFaultDetail | null {\n  if (!soapXml || !soapXml.includes('Fault')) return null;\n\n  const faultCodeMatch = soapXml.match(/<(?:[a-zA-Z0-9_-]+:)?faultcode>([\\s\\S]*?)<\\/(?:[a-zA-Z0-9_-]+:)?faultcode>/);\n  const faultStringMatch = soapXml.match(/<(?:[a-zA-Z0-9_-]+:)?faultstring>([\\s\\S]*?)<\\/(?:[a-zA-Z0-9_-]+:)?faultstring>/);\n  const detailMatch = soapXml.match(/<(?:[a-zA-Z0-9_-]+:)?detail>([\\s\\S]*?)<\\/(?:[a-zA-Z0-9_-]+:)?detail>/);\n\n  if (!faultCodeMatch && !faultStringMatch) return null;\n\n  const faultCode = faultCodeMatch ? faultCodeMatch[1].trim() : 'UnknownFault';\n  const faultString = faultStringMatch ? faultStringMatch[1].trim() : 'Error en el servicio SOAP de SUNAT';\n  const detail = detailMatch ? detailMatch[1].trim() : undefined;\n\n  const codeMatch = faultCode.match(/\\.(\\d+)$/) || faultString.match(/^(\\d{4})\\s*-/);\n  const sunatErrorCode = codeMatch ? codeMatch[1] : undefined;\n\n  return {\n    faultCode,\n    faultString,\n    detail,\n    sunatErrorCode,\n  };\n}\n",
  "src/modules/sunat-soap/cdr-parser.ts": "import { DOMParser } from '@xmldom/xmldom';\nimport { extractCpeZip } from '../packaging/index.js';\nimport type { SunatCdr, SunatCdrObservation } from './types.js';\n\n/**\n * Obtiene el texto del primer elemento coincidente ignorando prefijos de namespace.\n */\nfunction getElementText(doc: any, localName: string): string {\n  const elements = doc.getElementsByTagNameNS('*', localName);\n  if (elements.length > 0 && elements[0].textContent) {\n    return elements[0].textContent.trim();\n  }\n  // Fallback sin namespace por si acaso\n  const fallback = doc.getElementsByTagName(localName);\n  if (fallback.length > 0 && fallback[0].textContent) {\n    return fallback[0].textContent.trim();\n  }\n  return '';\n}\n\n/**\n * Parsea el XML de la Constancia de Recepción (ApplicationResponse) oficial de SUNAT.\n *\n * @param cdrXml Contenido XML del comprobante ApplicationResponse emitido por SUNAT\n * @param zipBase64 Archivo ZIP original en Base64 (opcional, para trazabilidad y guardado en BD)\n */\nexport function parseCdrXml(cdrXml: string, zipBase64?: string): SunatCdr {\n  if (!cdrXml || typeof cdrXml !== 'string') {\n    throw new Error('El XML de la CDR no puede estar vacío.');\n  }\n\n  const parser = new DOMParser();\n  const doc = parser.parseFromString(cdrXml, 'text/xml');\n\n  // Identificador propio de la CDR (ej. R-20600000001-01-F001-00000001)\n  const id = getElementText(doc, 'ID');\n  const issueDate = getElementText(doc, 'IssueDate');\n  const issueTime = getElementText(doc, 'IssueTime');\n  const responseDate = getElementText(doc, 'ResponseDate') || issueDate;\n  const responseTime = getElementText(doc, 'ResponseTime') || issueTime;\n\n  // Extraer información del emisor y receptor\n  let senderRuc = '';\n  const senderParty = doc.getElementsByTagNameNS('*', 'SenderParty');\n  if (senderParty.length > 0) {\n    senderRuc = getElementText(senderParty[0], 'ID');\n  }\n\n  let receiverRuc = '';\n  const receiverParty = doc.getElementsByTagNameNS('*', 'ReceiverParty');\n  if (receiverParty.length > 0) {\n    receiverRuc = getElementText(receiverParty[0], 'ID');\n  }\n\n  // DocumentResponse principal\n  let referenceId = '';\n  let responseCode = '';\n  let description = '';\n  let documentTypeCode = '';\n\n  const docResponses = doc.getElementsByTagNameNS('*', 'DocumentResponse');\n  if (docResponses.length > 0) {\n    const docResp = docResponses[0];\n\n    const responses = docResp.getElementsByTagNameNS('*', 'Response');\n    if (responses.length > 0) {\n      referenceId = getElementText(responses[0], 'ReferenceID');\n      responseCode = getElementText(responses[0], 'ResponseCode');\n      description = getElementText(responses[0], 'Description');\n    }\n\n    const docRefs = docResp.getElementsByTagNameNS('*', 'DocumentReference');\n    if (docRefs.length > 0) {\n      if (!referenceId) {\n        referenceId = getElementText(docRefs[0], 'ID');\n      }\n      documentTypeCode = getElementText(docRefs[0], 'DocumentTypeCode');\n    }\n  }\n\n  // Si no se ubicó dentro de DocumentResponse, buscar a nivel raíz\n  if (!referenceId) referenceId = getElementText(doc, 'ReferenceID');\n  if (!responseCode) responseCode = getElementText(doc, 'ResponseCode');\n  if (!description) description = getElementText(doc, 'Description');\n\n  // Extraer notas u observaciones (cbc:Note)\n  const notes: string[] = [];\n  const noteElements = doc.getElementsByTagNameNS('*', 'Note');\n  for (let i = 0; i < noteElements.length; i++) {\n    const noteText = noteElements[i].textContent?.trim();\n    if (noteText) {\n      notes.push(noteText);\n    }\n  }\n\n  // Extraer observaciones estructuradas\n  const observations: SunatCdrObservation[] = [];\n  const statusElements = doc.getElementsByTagNameNS('*', 'StatusReasonCode');\n  for (let i = 0; i < statusElements.length; i++) {\n    const code = statusElements[i].textContent?.trim() || '';\n    if (code) {\n      observations.push({\n        code,\n        message: notes.find((n) => n.startsWith(code)) || `Observación SUNAT código ${code}`,\n      });\n    }\n  }\n\n  // Si no vinieron StatusReasonCode pero hay Notes con códigos (ej. \"4010 - ...\")\n  if (observations.length === 0) {\n    for (const note of notes) {\n      const match = note.match(/^(\\d{4})\\s*[-:]\\s*(.*)$/);\n      if (match) {\n        observations.push({\n          code: match[1],\n          message: match[2].trim(),\n        });\n      }\n    }\n  }\n\n  // Hash y firma de SUNAT\n  const cdrHash = getElementText(doc, 'DigestValue') || undefined;\n  const signatureValue = getElementText(doc, 'SignatureValue')?.replace(/\\s+/g, '') || undefined;\n\n  const isAccepted = responseCode === '0';\n  const hasObservations = isAccepted && (observations.length > 0 || notes.length > 0);\n\n  return {\n    id,\n    referenceId,\n    documentTypeCode,\n    responseCode,\n    description,\n    isAccepted,\n    hasObservations,\n    observations,\n    notes,\n    issueDate,\n    issueTime,\n    responseDate,\n    responseTime,\n    senderRuc: senderRuc || undefined,\n    receiverRuc: receiverRuc || undefined,\n    cdrHash,\n    signatureValue,\n    xmlContent: cdrXml,\n    zipBase64,\n  };\n}\n\n/**\n * Descomprime un archivo ZIP de Constancia de Recepción (CDR) devuelto por SUNAT y parsea su XML.\n *\n * @param zipInput Buffer binario o cadena Base64 del ZIP de la CDR devuelto por sendBill\n */\nexport async function parseCdrFromZip(zipInput: Buffer | Uint8Array | string): Promise<SunatCdr> {\n  const zipBase64 = typeof zipInput === 'string' ? zipInput.replace(/\\s+/g, '') : Buffer.from(zipInput).toString('base64');\n  const unzipped = await extractCpeZip(zipInput);\n  return parseCdrXml(unzipped.xmlContent, zipBase64);\n}\n",
  "src/modules/sunat-soap/sunat-soap-client.ts": "import type { CpePackageInfo } from '../packaging/types.js';\nimport { createCpeZip } from '../packaging/zip-packager.js';\nimport { parseCdrFromZip } from './cdr-parser.js';\nimport {\n  SUNAT_ENDPOINTS,\n  buildSendBillEnvelope,\n  extractApplicationResponse,\n  parseSoapFault,\n} from './soap-envelope.js';\nimport type {\n  SendBillResult,\n  SendBillStatus,\n  SunatClientConfig,\n} from './types.js';\n\nexport class SunatSoapClient {\n  private config: SunatClientConfig;\n  private endpointUrl: string;\n  private fetchFn: typeof fetch;\n\n  constructor(config: SunatClientConfig) {\n    if (!config.credentials?.ruc || !config.credentials?.username || !config.credentials?.password) {\n      throw new Error('Credenciales SUNAT incompletas: se requiere ruc, username y password.');\n    }\n\n    this.config = config;\n    this.endpointUrl =\n      config.customUrl ||\n      (config.environment === 'production' ? SUNAT_ENDPOINTS.production : SUNAT_ENDPOINTS.beta);\n    this.fetchFn = config.fetchFn || (globalThis.fetch ? globalThis.fetch.bind(globalThis) : fetch);\n  }\n\n  /**\n   * Obtiene la URL configurada del servicio SOAP de SUNAT.\n   */\n  public getEndpointUrl(): string {\n    return this.endpointUrl;\n  }\n\n  /**\n   * Envía un archivo ZIP (CPE ya empaquetado) directamente a SUNAT mediante sendBill.\n   *\n   * @param fileName Nombre oficial del archivo (ej. 20600000001-01-F001-00000001.zip)\n   * @param zipBufferOrBase64 Buffer binario o cadena Base64 del archivo ZIP\n   */\n  public async sendBillZip(\n    fileName: string,\n    zipBufferOrBase64: Buffer | Uint8Array | string,\n  ): Promise<SendBillResult> {\n    const zipBase64 =\n      typeof zipBufferOrBase64 === 'string'\n        ? zipBufferOrBase64.replace(/\\s+/g, '')\n        : Buffer.from(zipBufferOrBase64).toString('base64');\n\n    const soapRequestXml = buildSendBillEnvelope(\n      this.config.credentials,\n      fileName,\n      zipBase64,\n    );\n\n    const timeoutMs = this.config.timeoutMs ?? 30000;\n    const controller = new AbortController();\n    const timeoutId = setTimeout(() => controller.abort(), timeoutMs);\n\n    try {\n      const response = await this.fetchFn(this.endpointUrl, {\n        method: 'POST',\n        headers: {\n          'Content-Type': 'text/xml; charset=utf-8',\n          'SOAPAction': '\"\"',\n          'Accept': 'text/xml, multipart/related, */*',\n          'User-Agent': 'AYSunat/1.0',\n        },\n        body: soapRequestXml,\n        signal: controller.signal,\n      });\n\n      clearTimeout(timeoutId);\n\n      const responseText = await response.text();\n\n      // 1. Verificar si la respuesta es un SOAP Fault (puede venir con HTTP 500 o 200)\n      const fault = parseSoapFault(responseText);\n      if (fault) {\n        return {\n          status: 'SOAP_FAULT',\n          httpStatusCode: response.status,\n          message: fault.faultString,\n          fault,\n          rawSoapResponse: responseText,\n        };\n      }\n\n      // 2. Extraer applicationResponse (Base64 del ZIP de la CDR)\n      const cdrZipBase64 = extractApplicationResponse(responseText);\n      if (!cdrZipBase64) {\n        return {\n          status: 'SOAP_FAULT',\n          httpStatusCode: response.status,\n          message: `Respuesta de SUNAT sin Constancia de Recepción (HTTP ${response.status}).`,\n          rawSoapResponse: responseText,\n        };\n      }\n\n      // 3. Descomprimir y parsear la CDR\n      const cdr = await parseCdrFromZip(cdrZipBase64);\n\n      let status: SendBillStatus = 'REJECTED';\n      if (cdr.isAccepted) {\n        status = cdr.hasObservations ? 'ACCEPTED_WITH_OBSERVATIONS' : 'ACCEPTED';\n      }\n\n      return {\n        status,\n        httpStatusCode: response.status,\n        message: cdr.description || (cdr.isAccepted ? 'Comprobante aceptado' : 'Comprobante rechazado'),\n        cdr,\n        rawSoapResponse: responseText,\n      };\n    } catch (err: any) {\n      clearTimeout(timeoutId);\n\n      if (err.name === 'AbortError') {\n        return {\n          status: 'NETWORK_ERROR',\n          httpStatusCode: 0,\n          message: `Tiempo de espera agotado (${timeoutMs}ms) al conectar con SUNAT.`,\n        };\n      }\n\n      return {\n        status: 'NETWORK_ERROR',\n        httpStatusCode: 0,\n        message: `Error de red al conectar con SUNAT: ${err.message || String(err)}`,\n      };\n    }\n  }\n\n  /**\n   * Método de alto nivel: toma el XML firmado del comprobante, lo empaqueta en ZIP con la\n   * nomenclatura oficial y lo transmite a SUNAT mediante sendBill, retornando la CDR procesada.\n   */\n  public async sendCpe(\n    packageInfo: CpePackageInfo,\n    signedXml: string,\n  ): Promise<SendBillResult> {\n    // 1. Crear el ZIP oficial {RUC}-{TIPO}-{SERIE}-{CORRELATIVO}.zip\n    const zipPackage = await createCpeZip(packageInfo, signedXml);\n\n    // 2. Transmitir por SOAP\n    return this.sendBillZip(zipPackage.zipFileName, zipPackage.zipBuffer);\n  }\n}\n",
  "src/modules/sunat-soap/index.ts": "export * from './types.js';\nexport * from './soap-envelope.js';\nexport * from './cdr-parser.js';\nexport * from './sunat-soap-client.js';\n",
  "src/modules/__tests__/signing-packaging.test.ts": "import { describe, expect, it } from 'vitest';\nimport {\n  generateSelfSignedCertificate,\n  loadCertificateFromPfx,\n  loadCertificateFromPem,\n  signUblXml,\n  extractHashCpe,\n  verifySignedXml,\n  type CertificateData,\n} from '../signing/index.js';\nimport {\n  formatCpeFileName,\n  createCpeZip,\n  extractCpeZip,\n} from '../packaging/index.js';\nimport { generateUblXml } from '../ubl/ubl-builder.js';\nimport { validateUblXmlAgainstXsd } from '../ubl/xsd-validator.js';\nimport type { CpeDocumentCalculationResult, CpeDocumentInput } from '../../core/tax-engine/types.js';\n\n// Empresa y cliente base para pruebas\nconst testCompany = {\n  ruc: '20600000001',\n  legalName: 'AYSunat Soluciones Tributarias SAC',\n  taxRegime: 'RMT' as const,\n  tradeName: 'AYSunat',\n  address: {\n    ubigeo: '150101',\n    department: 'LIMA',\n    province: 'LIMA',\n    district: 'LIMA',\n    addressLine: 'Av. Javier Prado Este 1234',\n  },\n};\n\nconst testClient = {\n  docType: '6' as const,\n  docNumber: '20123456789',\n  name: 'CLIENTE PRUEBA SAC',\n};\n\nfunction sampleCalculation(cpeType: '01' | '03' | '07', fullNumber: string): {\n  input: CpeDocumentInput;\n  calcResult: CpeDocumentCalculationResult;\n} {\n  const [series, correlativeStr] = fullNumber.split('-');\n  const correlative = parseInt(correlativeStr, 10);\n\n  const input: CpeDocumentInput = {\n    cpeType,\n    series,\n    correlative,\n    issueDate: '2026-11-20',\n    issueTime: '12:00:00',\n    currency: 'PEN',\n    company: testCompany,\n    client: testClient,\n    paymentMethod: 'CONTADO',\n    items: [\n      {\n        code: 'SERV01',\n        description: 'Servicio de desarrollo de software',\n        quantity: 1,\n        unitPrice: '118.00',\n        priceIncludesIgv: true,\n        affectationType: '10',\n        unitCode: 'NIU',\n      },\n    ],\n    creditNoteInfo:\n      cpeType === '07'\n        ? {\n            modifiedDocType: '01',\n            modifiedDocSeries: 'F001',\n            modifiedDocCorrelative: 1,\n            discrepancyCode: '01',\n            discrepancyReason: 'Anulacion de la operacion',\n          }\n        : undefined,\n  };\n\n  const calcResult: CpeDocumentCalculationResult = {\n    header: {\n      cpeType,\n      series,\n      correlative,\n      fullNumber,\n      issueDate: '2026-11-20',\n      currency: 'PEN',\n    },\n    items: [\n      {\n        code: 'SERV01',\n        description: 'Servicio de desarrollo de software',\n        unitCode: 'NIU',\n        quantity: '1',\n        unitValue: '100.00',\n        unitPrice: '118.00',\n        affectationType: '10',\n        baseAmount: '100.00',\n        discountAmount: '0.00',\n        igvAmount: '18.00',\n        totalAmount: '118.00',\n        isGratuitous: false,\n      },\n    ],\n    client: testClient,\n    sunatXmlReadyPayload: {} as any,\n    totals: {\n      operacionesGravadas: '100.00',\n      operacionesExoneradas: '0.00',\n      operacionesInafectas: '0.00',\n      operacionesGratuitas: '0.00',\n      totalDescuentos: '0.00',\n      descuentoGlobal: '0.00',\n      subTotal: '100.00',\n      montoIgv: '18.00',\n      totalPagar: '118.00',\n      totalEnLetras: 'CIENTO DIECIOCHO CON 00/100 SOLES',\n    },\n  };\n\n  return { input, calcResult };\n}\n\ndescribe('Firma Digital XMLDSig y Empaquetado ZIP para SUNAT', () => {\n  // Generar un certificado de prueba en memoria para la suite\n  const { pfxBuffer, password, certData } = generateSelfSignedCertificate('CERTIFICADO EMISOR SUNAT PRUEBA', 'test1234');\n\n  describe('1. Carga y gestión de Certificados Digitales', () => {\n    it('carga un certificado desde buffer PKCS#12 (.pfx)', () => {\n      const loaded = loadCertificateFromPfx(pfxBuffer, password);\n      expect(loaded.privateKeyPem).toContain('BEGIN RSA PRIVATE KEY');\n      expect(loaded.certificatePem).toContain('BEGIN CERTIFICATE');\n      expect(loaded.subject).toContain('CERTIFICADO EMISOR SUNAT PRUEBA');\n      expect(loaded.validTo).toBeInstanceOf(Date);\n    });\n\n    it('falla si la contraseña del PFX es incorrecta', () => {\n      expect(() => loadCertificateFromPfx(pfxBuffer, 'clave_invalida')).toThrow();\n    });\n\n    it('carga un certificado desde cadenas PEM', () => {\n      const loaded = loadCertificateFromPem(certData.privateKeyPem, certData.certificatePem);\n      expect(loaded.privateKeyPem).toBe(certData.privateKeyPem);\n      expect(loaded.certificatePem).toBe(certData.certificatePem);\n    });\n  });\n\n  describe('2. Firma Digital de Factura (01) y validación XSD', () => {\n    it('firma una Factura, extrae el Hash CPE y valida contra XSD oficial', async () => {\n      const { input, calcResult } = sampleCalculation('01', 'F001-00000001');\n      const unsignedXml = generateUblXml(calcResult, input);\n\n      const signResult = signUblXml(unsignedXml, certData, { signatureId: 'SignatureSP' });\n\n      expect(signResult.signedXml).toContain('<Signature Id=\"SignatureSP\"');\n      expect(signResult.signedXml).toContain('<DigestValue>');\n      expect(signResult.signedXml).toContain('<SignatureValue>');\n      expect(signResult.hashCpe).toBeTruthy();\n      expect(signResult.hashCpe.length).toBeGreaterThan(10);\n\n      // Verificación de extracción de hash\n      const extractedHash = extractHashCpe(signResult.signedXml);\n      expect(extractedHash).toBe(signResult.hashCpe);\n\n      // Verificación XSD oficial\n      const xsdCheck = await validateUblXmlAgainstXsd(signResult.signedXml, '01');\n      expect(xsdCheck.valid).toBe(true);\n      expect(xsdCheck.errors).toHaveLength(0);\n    });\n  });\n\n  describe('3. Firma Digital de Boleta (03) y Nota de Crédito (07)', () => {\n    it('firma una Boleta de Venta y es válida contra el XSD de SUNAT', async () => {\n      const { input, calcResult } = sampleCalculation('03', 'B001-00000001');\n      const unsignedXml = generateUblXml(calcResult, input);\n\n      const signResult = signUblXml(unsignedXml, certData);\n      expect(signResult.hashCpe).toBeTruthy();\n\n      const xsdCheck = await validateUblXmlAgainstXsd(signResult.signedXml, '03');\n      expect(xsdCheck.valid).toBe(true);\n    });\n\n    it('firma una Nota de Crédito y es válida contra UBL-CreditNote-2.1.xsd', async () => {\n      const { input, calcResult } = sampleCalculation('07', 'FC01-00000001');\n      const unsignedXml = generateUblXml(calcResult, input);\n\n      const signResult = signUblXml(unsignedXml, certData);\n      expect(signResult.hashCpe).toBeTruthy();\n\n      const xsdCheck = await validateUblXmlAgainstXsd(signResult.signedXml, '07');\n      expect(xsdCheck.valid).toBe(true);\n    });\n  });\n\n  describe('4. Integridad criptográfica y detección de alteraciones', () => {\n    it('valida exitosamente la firma criptográfica usando el certificado incrustado', () => {\n      const { input, calcResult } = sampleCalculation('01', 'F001-00000002');\n      const xml = generateUblXml(calcResult, input);\n      const { signedXml } = signUblXml(xml, certData);\n\n      const verifyResult = verifySignedXml(signedXml);\n      expect(verifyResult.isValid).toBe(true);\n      expect(verifyResult.error).toBeUndefined();\n    });\n\n    it('detecta si el XML fue alterado después de firmar (tamper detection)', () => {\n      const { input, calcResult } = sampleCalculation('01', 'F001-00000003');\n      const xml = generateUblXml(calcResult, input);\n      const { signedXml } = signUblXml(xml, certData);\n\n      // Intentamos alterar maliciosamente el total a pagar de 118.00 a 999.00\n      const tamperedXml = signedXml.replace(\n        '<cbc:PayableAmount currencyID=\"PEN\">118.00</cbc:PayableAmount>',\n        '<cbc:PayableAmount currencyID=\"PEN\">999.00</cbc:PayableAmount>',\n      );\n\n      const verifyResult = verifySignedXml(tamperedXml);\n      expect(verifyResult.isValid).toBe(false);\n      expect(verifyResult.error).toBeDefined();\n    });\n  });\n\n  describe('5. Nomenclatura y empaquetado ZIP oficial SUNAT', () => {\n    it('formatea correctamente el nombre oficial {RUC}-{TIPO}-{SERIE}-{CORRELATIVO}', () => {\n      const name = formatCpeFileName({\n        ruc: '20600000001',\n        cpeType: '01',\n        series: 'F001',\n        correlative: 42,\n      });\n      expect(name).toBe('20600000001-01-F001-00000042');\n    });\n\n    it('valida datos erróneos en el nombre del comprobante', () => {\n      expect(() => formatCpeFileName({ ruc: '123', cpeType: '01', series: 'F001', correlative: 1 })).toThrow(/RUC/);\n      expect(() => formatCpeFileName({ ruc: '20600000001', cpeType: '999', series: 'F001', correlative: 1 })).toThrow(/Tipo/);\n      expect(() => formatCpeFileName({ ruc: '20600000001', cpeType: '01', series: 'SERIE_MUY_LARGA', correlative: 1 })).toThrow(/Serie/);\n    });\n\n    it('crea el archivo ZIP oficial y permite descomprimirlo manteniendo integridad', async () => {\n      const { input, calcResult } = sampleCalculation('01', 'F001-00000005');\n      const xml = generateUblXml(calcResult, input);\n      const { signedXml } = signUblXml(xml, certData);\n\n      const zipResult = await createCpeZip(\n        {\n          ruc: testCompany.ruc,\n          cpeType: '01',\n          series: 'F001',\n          correlative: 5,\n        },\n        signedXml,\n      );\n\n      expect(zipResult.baseName).toBe('20600000001-01-F001-00000005');\n      expect(zipResult.zipFileName).toBe('20600000001-01-F001-00000005.zip');\n      expect(zipResult.xmlFileName).toBe('20600000001-01-F001-00000005.xml');\n      expect(zipResult.zipBuffer).toBeInstanceOf(Buffer);\n      expect(zipResult.fileSize).toBeGreaterThan(200);\n      expect(zipResult.zipBase64).toBeTruthy();\n\n      // Descomprimir y verificar contenido\n      const unzipped = await extractCpeZip(zipResult.zipBuffer);\n      expect(unzipped.xmlFileName).toBe('20600000001-01-F001-00000005.xml');\n      expect(unzipped.xmlContent).toBe(signedXml);\n    });\n  });\n});\n",
  "src/modules/__tests__/sunat-soap.test.ts": "import { describe, expect, it, vi } from 'vitest';\nimport JSZip from 'jszip';\nimport {\n  SUNAT_ENDPOINTS,\n  SunatSoapClient,\n  buildSendBillEnvelope,\n  extractApplicationResponse,\n  parseCdrFromZip,\n  parseCdrXml,\n  parseSoapFault,\n  type SunatCredentials,\n} from '../sunat-soap/index.js';\nimport {\n  generateSelfSignedCertificate,\n  signUblXml,\n} from '../signing/index.js';\nimport { generateUblXml } from '../ubl/ubl-builder.js';\nimport type { CpeDocumentCalculationResult, CpeDocumentInput } from '../../core/tax-engine/types.js';\n\n// XML de CDR de prueba: Comprobante Aceptado\nfunction createSampleCdrXml(options: {\n  id?: string;\n  referenceId?: string;\n  responseCode?: string;\n  description?: string;\n  notes?: string[];\n} = {}): string {\n  const id = options.id ?? 'R-20600000001-01-F001-00000001';\n  const referenceId = options.referenceId ?? 'F001-00000001';\n  const responseCode = options.responseCode ?? '0';\n  const description = options.description ?? `La Factura numero ${referenceId}, ha sido aceptada`;\n  const notesXml = (options.notes || []).map((n) => `<cbc:Note>${n}</cbc:Note>`).join('\\n  ');\n\n  return `<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<ar:ApplicationResponse xmlns:ar=\"urn:oasis:names:specification:ubl:schema:xsd:ApplicationResponse-2\"\n                        xmlns:cac=\"urn:oasis:names:specification:ubl:schema:xsd:CommonAggregateComponents-2\"\n                        xmlns:cbc=\"urn:oasis:names:specification:ubl:schema:xsd:CommonBasicComponents-2\"\n                        xmlns:ds=\"http://www.w3.org/2000/09/xmldsig#\">\n  <cbc:UBLVersionID>2.0</cbc:UBLVersionID>\n  <cbc:CustomizationID>1.0</cbc:CustomizationID>\n  <cbc:ID>${id}</cbc:ID>\n  <cbc:IssueDate>2026-11-20</cbc:IssueDate>\n  <cbc:IssueTime>14:30:00</cbc:IssueTime>\n  <cbc:ResponseDate>2026-11-20</cbc:ResponseDate>\n  <cbc:ResponseTime>14:30:02</cbc:ResponseTime>\n  <cac:Signature>\n    <cbc:ID>SignSUNAT</cbc:ID>\n    <ds:Signature>\n      <ds:SignedInfo>\n        <ds:Reference>\n          <ds:DigestValue>SUNAT_HASH_DIGEST_ABC123==</ds:DigestValue>\n        </ds:Reference>\n      </ds:SignedInfo>\n      <ds:SignatureValue>SUNAT_SIGNATURE_VALUE_XYZ==</ds:SignatureValue>\n    </ds:Signature>\n  </cac:Signature>\n  <cac:SenderParty>\n    <cac:PartyIdentification>\n      <cbc:ID schemeID=\"6\">20131312955</cbc:ID>\n    </cac:PartyIdentification>\n    <cac:PartyLegalEntity>\n      <cbc:RegistrationName>SUPERINTENDENCIA NACIONAL DE ADUANAS Y DE ADMINISTRACION TRIBUTARIA</cbc:RegistrationName>\n    </cac:PartyLegalEntity>\n  </cac:SenderParty>\n  <cac:ReceiverParty>\n    <cac:PartyIdentification>\n      <cbc:ID schemeID=\"6\">20600000001</cbc:ID>\n    </cac:PartyIdentification>\n  </cac:ReceiverParty>\n  <cac:DocumentResponse>\n    <cac:Response>\n      <cbc:ReferenceID>${referenceId}</cbc:ReferenceID>\n      <cbc:ResponseCode>${responseCode}</cbc:ResponseCode>\n      <cbc:Description>${description}</cbc:Description>\n    </cac:Response>\n    <cac:DocumentReference>\n      <cbc:ID>${referenceId}</cbc:ID>\n      <cbc:DocumentTypeCode>01</cbc:DocumentTypeCode>\n    </cac:DocumentReference>\n  </cac:DocumentResponse>\n  ${notesXml}\n</ar:ApplicationResponse>`.trim();\n}\n\nasync function createSampleCdrZipBase64(cdrXml: string, fileName = 'R-20600000001-01-F001-00000001.xml'): Promise<string> {\n  const zip = new JSZip();\n  zip.file(fileName, cdrXml);\n  const buffer = await zip.generateAsync({ type: 'nodebuffer', compression: 'DEFLATE' });\n  return buffer.toString('base64');\n}\n\nfunction createSendBillSoapResponse(applicationResponseBase64: string): string {\n  return `<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<soapenv:Envelope xmlns:soapenv=\"http://schemas.xmlsoap.org/soap/envelope/\"\n                  xmlns:ser=\"http://service.sunat.gob.pe\">\n  <soapenv:Body>\n    <ser:sendBillResponse>\n      <applicationResponse>${applicationResponseBase64}</applicationResponse>\n    </ser:sendBillResponse>\n  </soapenv:Body>\n</soapenv:Envelope>`.trim();\n}\n\ndescribe('Cliente SOAP sendBill y Procesamiento de CDR SUNAT', () => {\n  const testCredentials: SunatCredentials = {\n    ruc: '20600000001',\n    username: 'MODDATOS',\n    password: 'moddatos_password',\n  };\n\n  describe('1. Construcción del sobre SOAP 1.1 y WS-Security', () => {\n    it('construye el sobre SOAP sendBill con UsernameToken conforme a SUNAT', () => {\n      const envelope = buildSendBillEnvelope(\n        testCredentials,\n        '20600000001-01-F001-00000001.zip',\n        'UEsDBBQAAAAIA...',\n      );\n\n      // Verificación de namespaces\n      expect(envelope).toContain('xmlns:soapenv=\"http://schemas.xmlsoap.org/soap/envelope/\"');\n      expect(envelope).toContain('xmlns:ser=\"http://service.sunat.gob.pe\"');\n      expect(envelope).toContain('xmlns:wsse=\"http://docs.oasis-open.org/wss/2004/01/oasis-200401-wss-wssecurity-secext-1.0.xsd\"');\n\n      // Verificación de credenciales concatenadas {RUC}{USUARIO}\n      expect(envelope).toContain('<wsse:Username>20600000001MODDATOS</wsse:Username>');\n      expect(envelope).toContain('<wsse:Password Type=\"http://docs.oasis-open.org/wss/2004/01/oasis-200401-wss-username-token-profile-1.0#PasswordText\">moddatos_password</wsse:Password>');\n\n      // Verificación de parámetros de la operación sendBill\n      expect(envelope).toContain('<fileName>20600000001-01-F001-00000001.zip</fileName>');\n      expect(envelope).toContain('<contentFile>UEsDBBQAAAAIA...</contentFile>');\n    });\n\n    it('escapa caracteres especiales en las credenciales o nombre de archivo', () => {\n      const envelope = buildSendBillEnvelope(\n        { ruc: '20600000001', username: 'USER&<1>', password: 'pass\"word\\'' },\n        'test&file.zip',\n        'BASE64',\n      );\n      expect(envelope).toContain('USER&amp;&lt;1&gt;');\n      expect(envelope).toContain('pass&quot;word&apos;');\n      expect(envelope).toContain('test&amp;file.zip');\n    });\n  });\n\n  describe('2. Detección y parseo de SOAP Faults', () => {\n    it('extrae el código de error y mensaje de un SOAP Fault de SUNAT', () => {\n      const faultXml = `\n      <soapenv:Envelope xmlns:soapenv=\"http://schemas.xmlsoap.org/soap/envelope/\">\n        <soapenv:Body>\n          <soapenv:Fault>\n            <faultcode>soap-env:Client.1033</faultcode>\n            <faultstring>El comprobante fue registrado previamente con otros datos</faultstring>\n            <detail>Validacion rechazada por sistema de recepcion</detail>\n          </soapenv:Fault>\n        </soapenv:Body>\n      </soapenv:Envelope>`;\n\n      const fault = parseSoapFault(faultXml);\n      expect(fault).not.toBeNull();\n      expect(fault?.faultCode).toBe('soap-env:Client.1033');\n      expect(fault?.faultString).toContain('registrado previamente');\n      expect(fault?.sunatErrorCode).toBe('1033');\n      expect(fault?.detail).toBe('Validacion rechazada por sistema de recepcion');\n    });\n\n    it('detecta código de error numérico al inicio de faultstring', () => {\n      const faultXml = `\n      <soapenv:Envelope xmlns:soapenv=\"http://schemas.xmlsoap.org/soap/envelope/\">\n        <soapenv:Body>\n          <soapenv:Fault>\n            <faultcode>soap-env:Client</faultcode>\n            <faultstring>0156 - El archivo ZIP esta corrupto</faultstring>\n          </soapenv:Fault>\n        </soapenv:Body>\n      </soapenv:Envelope>`;\n\n      const fault = parseSoapFault(faultXml);\n      expect(fault?.sunatErrorCode).toBe('0156');\n    });\n\n    it('retorna null si la respuesta no es un Fault', () => {\n      expect(parseSoapFault('<response>OK</response>')).toBeNull();\n    });\n  });\n\n  describe('3. Parseo de Constancia de Recepción (CDR) XML y ZIP', () => {\n    it('parsea exitosamente un CDR de comprobante ACEPTADO (ResponseCode = 0)', () => {\n      const xml = createSampleCdrXml({\n        id: 'R-20600000001-01-F001-00000001',\n        referenceId: 'F001-00000001',\n        responseCode: '0',\n        description: 'La Factura numero F001-00000001, ha sido aceptada',\n      });\n\n      const cdr = parseCdrXml(xml);\n\n      expect(cdr.id).toBe('R-20600000001-01-F001-00000001');\n      expect(cdr.referenceId).toBe('F001-00000001');\n      expect(cdr.documentTypeCode).toBe('01');\n      expect(cdr.responseCode).toBe('0');\n      expect(cdr.isAccepted).toBe(true);\n      expect(cdr.hasObservations).toBe(false);\n      expect(cdr.description).toContain('ha sido aceptada');\n      expect(cdr.senderRuc).toBe('20131312955');\n      expect(cdr.receiverRuc).toBe('20600000001');\n      expect(cdr.cdrHash).toBe('SUNAT_HASH_DIGEST_ABC123==');\n      expect(cdr.signatureValue).toBe('SUNAT_SIGNATURE_VALUE_XYZ==');\n    });\n\n    it('parsea un CDR ACEPTADO CON OBSERVACIONES (ResponseCode = 0 con notas 4000+)', () => {\n      const xml = createSampleCdrXml({\n        responseCode: '0',\n        description: 'El comprobante ha sido aceptado con observaciones',\n        notes: [\n          '4010 - El numero de RUC no coincide con el padron de contribuyentes activos.',\n          '4012 - La fecha de emision difiere de la fecha actual.',\n        ],\n      });\n\n      const cdr = parseCdrXml(xml);\n\n      expect(cdr.isAccepted).toBe(true);\n      expect(cdr.hasObservations).toBe(true);\n      expect(cdr.notes).toHaveLength(2);\n      expect(cdr.observations).toHaveLength(2);\n      expect(cdr.observations[0].code).toBe('4010');\n      expect(cdr.observations[0].message).toContain('padron de contribuyentes');\n      expect(cdr.observations[1].code).toBe('4012');\n    });\n\n    it('parsea un CDR RECHAZADO por SUNAT (ResponseCode != 0)', () => {\n      const xml = createSampleCdrXml({\n        responseCode: '2017',\n        description: 'El RUC del receptor no se encuentra en estado ACTIVO.',\n      });\n\n      const cdr = parseCdrXml(xml);\n\n      expect(cdr.isAccepted).toBe(false);\n      expect(cdr.responseCode).toBe('2017');\n      expect(cdr.hasObservations).toBe(false);\n      expect(cdr.description).toContain('no se encuentra en estado ACTIVO');\n    });\n\n    it('descomprime y parsea directamente desde el ZIP de la CDR', async () => {\n      const cdrXml = createSampleCdrXml({ referenceId: 'F001-00000009' });\n      const zipBase64 = await createSampleCdrZipBase64(cdrXml, 'R-20600000001-01-F001-00000009.xml');\n\n      const cdr = await parseCdrFromZip(zipBase64);\n      expect(cdr.referenceId).toBe('F001-00000009');\n      expect(cdr.isAccepted).toBe(true);\n      expect(cdr.zipBase64).toBe(zipBase64);\n    });\n  });\n\n  describe('4. Cliente SunatSoapClient con simulación HTTP', () => {\n    it('configura correctamente endpoints de Beta y Producción', () => {\n      const betaClient = new SunatSoapClient({ credentials: testCredentials, environment: 'beta' });\n      expect(betaClient.getEndpointUrl()).toBe(SUNAT_ENDPOINTS.beta);\n\n      const prodClient = new SunatSoapClient({ credentials: testCredentials, environment: 'production' });\n      expect(prodClient.getEndpointUrl()).toBe(SUNAT_ENDPOINTS.production);\n\n      const customClient = new SunatSoapClient({\n        credentials: testCredentials,\n        customUrl: 'http://localhost:8080/sunat/mock',\n      });\n      expect(customClient.getEndpointUrl()).toBe('http://localhost:8080/sunat/mock');\n    });\n\n    it('procesa respuesta HTTP 200 exitosa y devuelve estado ACCEPTED con CDR', async () => {\n      const cdrXml = createSampleCdrXml({ referenceId: 'F001-00000001' });\n      const zipBase64 = await createSampleCdrZipBase64(cdrXml);\n      const soapResponse = createSendBillSoapResponse(zipBase64);\n\n      const mockFetch = vi.fn().mockResolvedValue({\n        status: 200,\n        ok: true,\n        text: async () => soapResponse,\n      });\n\n      const client = new SunatSoapClient({\n        credentials: testCredentials,\n        fetchFn: mockFetch as any,\n      });\n\n      const result = await client.sendBillZip('20600000001-01-F001-00000001.zip', 'BASE64_ZIP_CPE');\n\n      expect(mockFetch).toHaveBeenCalledTimes(1);\n      expect(result.status).toBe('ACCEPTED');\n      expect(result.httpStatusCode).toBe(200);\n      expect(result.cdr).toBeDefined();\n      expect(result.cdr?.isAccepted).toBe(true);\n      expect(result.cdr?.referenceId).toBe('F001-00000001');\n    });\n\n    it('procesa respuesta HTTP 500 con SOAP Fault de SUNAT', async () => {\n      const soapFaultResponse = `\n      <soapenv:Envelope xmlns:soapenv=\"http://schemas.xmlsoap.org/soap/envelope/\">\n        <soapenv:Body>\n          <soapenv:Fault>\n            <faultcode>soap-env:Client.0156</faultcode>\n            <faultstring>El archivo ZIP esta corrupto</faultstring>\n          </soapenv:Fault>\n        </soapenv:Body>\n      </soapenv:Envelope>`;\n\n      const mockFetch = vi.fn().mockResolvedValue({\n        status: 500,\n        ok: false,\n        text: async () => soapFaultResponse,\n      });\n\n      const client = new SunatSoapClient({\n        credentials: testCredentials,\n        fetchFn: mockFetch as any,\n      });\n\n      const result = await client.sendBillZip('20600000001-01-F001-00000001.zip', 'BAD_BASE64');\n\n      expect(result.status).toBe('SOAP_FAULT');\n      expect(result.httpStatusCode).toBe(500);\n      expect(result.fault?.sunatErrorCode).toBe('0156');\n      expect(result.fault?.faultString).toBe('El archivo ZIP esta corrupto');\n      expect(result.cdr).toBeUndefined();\n    });\n\n    it('maneja errores de red o conexión caída de manera limpia', async () => {\n      const mockFetch = vi.fn().mockRejectedValue(new Error('Connection refused to e-beta.sunat.gob.pe'));\n\n      const client = new SunatSoapClient({\n        credentials: testCredentials,\n        fetchFn: mockFetch as any,\n      });\n\n      const result = await client.sendBillZip('20600000001-01-F001-00000001.zip', 'DUMMY');\n\n      expect(result.status).toBe('NETWORK_ERROR');\n      expect(result.httpStatusCode).toBe(0);\n      expect(result.message).toContain('Connection refused');\n    });\n  });\n\n  describe('5. Flujo integral sendCpe (UBL -> Firma -> ZIP -> SOAP -> CDR)', () => {\n    it('ejecuta el ciclo de vida completo de emisión y recepción', async () => {\n      // 1. Datos del comprobante\n      const input: CpeDocumentInput = {\n        cpeType: '01',\n        series: 'F001',\n        correlative: 10,\n        issueDate: '2026-11-20',\n        issueTime: '12:00:00',\n        currency: 'PEN',\n        company: {\n          ruc: '20600000001',\n          legalName: 'AYSunat Soluciones SAC',\n          taxRegime: 'RMT' as const,\n          tradeName: 'AYSunat',\n          address: {\n            ubigeo: '150101',\n            department: 'LIMA',\n            province: 'LIMA',\n            district: 'LIMA',\n            addressLine: 'Av. Javier Prado 123',\n          },\n        },\n        client: {\n          docType: '6' as const,\n          docNumber: '20123456789',\n          name: 'CLIENTE PRUEBA SAC',\n        },\n        paymentMethod: 'CONTADO',\n        items: [\n          {\n            code: 'PROD01',\n            description: 'Licencia de Software',\n            quantity: 1,\n            unitPrice: '118.00',\n            priceIncludesIgv: true,\n            affectationType: '10',\n            unitCode: 'NIU',\n          },\n        ],\n      };\n\n      const calcResult: CpeDocumentCalculationResult = {\n        header: {\n          cpeType: '01',\n          series: 'F001',\n          correlative: 10,\n          fullNumber: 'F001-00000010',\n          issueDate: '2026-11-20',\n          currency: 'PEN',\n        },\n        items: [\n          {\n            code: 'PROD01',\n            description: 'Licencia de Software',\n            unitCode: 'NIU',\n            quantity: '1',\n            unitValue: '100.00',\n            unitPrice: '118.00',\n            affectationType: '10',\n            baseAmount: '100.00',\n            discountAmount: '0.00',\n            igvAmount: '18.00',\n            totalAmount: '118.00',\n            isGratuitous: false,\n          },\n        ],\n        client: input.client,\n        sunatXmlReadyPayload: {} as any,\n        totals: {\n          operacionesGravadas: '100.00',\n          operacionesExoneradas: '0.00',\n          operacionesInafectas: '0.00',\n          operacionesGratuitas: '0.00',\n          totalDescuentos: '0.00',\n          descuentoGlobal: '0.00',\n          subTotal: '100.00',\n          montoIgv: '18.00',\n          totalPagar: '118.00',\n          totalEnLetras: 'CIENTO DIECIOCHO CON 00/100 SOLES',\n        },\n      };\n\n      // 2. Generar y firmar XML\n      const { certData } = generateSelfSignedCertificate('EMPRESA PRUEBA SAC');\n      const unsignedXml = generateUblXml(calcResult, input);\n      const { signedXml, hashCpe } = signUblXml(unsignedXml, certData);\n      expect(hashCpe).toBeTruthy();\n\n      // 3. Simular que SUNAT responde con CDR aceptando F001-00000010\n      const cdrXml = createSampleCdrXml({\n        id: 'R-20600000001-01-F001-00000010',\n        referenceId: 'F001-00000010',\n        responseCode: '0',\n        description: 'La Factura numero F001-00000010, ha sido aceptada',\n      });\n      const cdrZipBase64 = await createSampleCdrZipBase64(cdrXml, 'R-20600000001-01-F001-00000010.xml');\n      const soapResponse = createSendBillSoapResponse(cdrZipBase64);\n\n      let capturedRequestBody = '';\n      const mockFetch = vi.fn().mockImplementation(async (url, init) => {\n        capturedRequestBody = init.body;\n        return {\n          status: 200,\n          ok: true,\n          text: async () => soapResponse,\n        };\n      });\n\n      const client = new SunatSoapClient({\n        credentials: testCredentials,\n        fetchFn: mockFetch as any,\n      });\n\n      // 4. Enviar mediante sendCpe\n      const sendResult = await client.sendCpe(\n        {\n          ruc: '20600000001',\n          cpeType: '01',\n          series: 'F001',\n          correlative: 10,\n        },\n        signedXml,\n      );\n\n      // Verificaciones\n      expect(capturedRequestBody).toContain('<fileName>20600000001-01-F001-00000010.zip</fileName>');\n      expect(sendResult.status).toBe('ACCEPTED');\n      expect(sendResult.cdr?.isAccepted).toBe(true);\n      expect(sendResult.cdr?.referenceId).toBe('F001-00000010');\n      expect(sendResult.cdr?.description).toContain('ha sido aceptada');\n      expect(sendResult.cdr?.senderRuc).toBe('20131312955');\n    });\n  });\n});\n"
};

for (const [relPath, content] of Object.entries(files)) {
  const targetPath = path.resolve(process.cwd(), relPath);
  fs.mkdirSync(path.dirname(targetPath), { recursive: true });
  fs.writeFileSync(targetPath, content, "utf8");
  console.log("✓ Creado:", relPath);
}

